import type { AlertSeverity } from './alerts.js';
import type { TargetId } from './targets.js';

// --- Agents (enrolment tokens) ----------------------------------------------

export interface AgentToken {
	id: number;
	/** Opaque identifier generated by the server (`tok_` + 10 base32 characters); never editable. */
	name: string;
	/** Start of the token, to identify it in a list. */
	prefix: string;
	created_at: string;
	last_used_at: string | null;
	revoked_at: string | null;
	/** How many machines this token may enrol in total. `null` means a fleet token, with no limit. */
	max_uses: number | null;
	/** How many machines it has already enrolled. */
	uses: number;
	/**
	 * When it stops enrolling. Machines already enrolled keep reporting after
	 * this date — only revoking cuts them off.
	 */
	expires_at: string | null;
	/** A relay token: the machine it enrols becomes a relay for its site at its first report. */
	relay?: boolean;
	relay_site?: string | null;
	/** Active Directory domain this fleet token was made for; `null` for an ordinary token. */
	ad_domain: string | null;
	/** MSP mode: the client this token enrols into, and the only one its machines report to. */
	client_id?: number;
	/**
	 * A fleet token put to sleep after enrolling no machine for the configured
	 * days: it refuses new enrolments until reactivated. `null` (or absent on an
	 * older server) while in service.
	 */
	dormant_at?: string | null;
}

// --- Agents (enrolment approval) ----------------------------------------------

/** What the server does with a machine it does not know yet. */
export type EnrolmentApprovalMode = 'auto' | 'manual' | 'ad_domain';

/** `GET`/`PUT /api/agent/enrolment` settings. */
export interface AgentEnrolmentSettings {
	/** Machines enrolled with a fleet (reusable) token. */
	fleet_approval: EnrolmentApprovalMode;
	/** Machines enrolled with a single-use token. */
	single_use_approval: EnrolmentApprovalMode;
	/** Enrolments per token per hour; 0 means no limit. */
	rate_per_hour: number;
	/** Days without enrolment before a fleet token is put to sleep; 0 means never. */
	dormant_days: number;
}

/** A machine waiting for approval. */
export interface AgentEnrolmentRequest {
	id: number;
	hostname: string;
	os: string;
	source_ip: string | null;
	token_id: number | null;
	/** Identifier of the enrolment token used, never its secret. */
	token_name: string | null;
	requested_at: string;
	last_seen_at: string;
}

export interface AgentEnrolmentOverview {
	settings: AgentEnrolmentSettings;
	pending: AgentEnrolmentRequest[];
	/** Beyond this many waiting machines, new requests are refused. */
	max_pending: number;
	/** Hours a rejected machine stays hidden. */
	reject_hold_hours: number;
}

/** Body of `POST /api/agent/tokens`. Omitting everything gives a single-use token. */
export interface AgentTokenPayload {
	base_url: string;
	/** Reusable for a fleet. Left out, the token enrols exactly one machine. */
	reusable?: boolean;
	/** Enrolments allowed for a reusable token. Left out, there is no limit. */
	max_uses?: number | null;
	/** Days before the token stops enrolling. Left out, there is no deadline. */
	expires_in_days?: number | null;
	/** Make the enrolled machine a relay for a remote site, without editing anything on it. */
	relay?: boolean;
	/** Site of that relay. */
	site?: string | null;
	/** MSP mode: the client the token enrols into. Absent: the default client. */
	client_id?: number;
	/**
	 * Install through this relay agent (a site behind a firewall): the commands
	 * point at its gateway, which the server asks the relay to open.
	 */
	relay_id?: TargetId | null;
	/** Address the site reaches the relay at. Left out: the one set, else its host name. */
	relay_host?: string | null;
	/** Commands that use the agent port only (a remote site). Always on for a relay token. */
	agent_port_only?: boolean;
	/**
	 * Transport of the encrypted channel in the commands. `auto` (default): the
	 * WebSocket through the web address when the server sees a proxy in front.
	 */
	transport?: AgentTransportWish;
}

/**
 * Transport of the encrypted agent channel asked for an install command:
 * `websocket` through the web address, `direct` to the agent port, `auto` lets
 * the server decide (the WebSocket when the browser address is served by
 * another certificate than DumbMonit's and no dedicated agent address is set).
 */
export type AgentTransportWish = 'auto' | 'websocket' | 'direct';

/** A machine enrolled with a token. `GET /api/agent/tokens/{id}/machines`. */
export interface TokenMachine {
	/** Id of the agent's target. */
	id: TargetId;
	name: string;
	hostname: string;
	os: string;
	last_seen_at: string | null;
	/** Relay the machine connects through, if any. */
	via_agent: TargetId | null;
}

/** Response of `POST /api/agent/tokens`: the only chance to see the token in clear. */
export interface CreatedAgentToken extends AgentToken {
	secret: string;
	install_linux: string;
	install_windows: string;
	/** Origin of the `--pinned-key` in the commands, when the server probed the opened address. */
	pin_source?: 'own' | 'proxy' | 'trusted' | null;
	/** `websocket`: the commands send the agent through the web address (`--transport=websocket`). */
	transport?: 'websocket' | null;
}

/** Channel an agent last reported through. Mirrors `AgentChannel` in `crates/server/src/api/agent_tls.rs`. */
export interface AgentChannelEntry {
	/** Id of the agent's target. */
	id: TargetId;
	/** `mtls`: encrypted agent port; `legacy`: plain channel of the web port; `none`: never seen. */
	channel: 'mtls' | 'legacy' | 'none';
	/** Key exchange negotiated at the last encrypted report, e.g. `X25519MLKEM768`. */
	group: string | null;
	tls_seen_at: string | null;
	legacy_seen_at: string | null;
}

/** `GET /api/agent/tls`. Mirrors `Overview` in `crates/server/src/api/agent_tls.rs`. */
export interface AgentChannelOverview {
	/** The agent port is open (`DUMBMONIT_AGENT_LISTEN`). */
	enabled: boolean;
	port: number | null;
	/** The plain channel is refused right now. */
	required: boolean;
	/** The setting as the administrator set it. */
	required_setting: boolean;
	/** End of the transition set by `DUMBMONIT_AGENT_LEGACY_DAYS`. */
	legacy_until: string | null;
	protocol: string;
	key_exchange: string;
	/** SHA-256 fingerprint of the active certificate authority. */
	ca_pin: string | null;
	rotation: { started_at: string | null; next_pin: string; ready: number; total: number } | null;
	agents: AgentChannelEntry[];
}

/** Body of `POST /api/agent/ad-kit`: a fleet token plus the GPO deployment script. */
export interface AdKitPayload {
	domain: string;
	base_url?: string;
	/** Servers allowed to enrol. `null` or left out: no limit. */
	max_uses?: number | null;
	/** Days the token may enrol servers. `null`, `0` or left out: never expires. */
	expires_in_days?: number | null;
	/** Cover every Windows Server of the domain, future ones included (script default `-AllServers`). Not with `security_group`. */
	all_servers?: boolean;
	/** Distinguished name of the OU the policy is linked to. Left out: the whole domain. */
	target_ou?: string | null;
	include_domain_controllers?: boolean;
	/** Security group that filters which servers receive the agent. */
	security_group?: string | null;
	/** Also copy the agent binary into SYSVOL, for servers without outbound access. */
	sysvol_binary?: boolean;
	/** DNS name (FQDN) or IPv4 address of this server that agents contact, optional `:port`. */
	server_host?: string | null;
	/** IP address of a DNS server that resolves `server_host` on machines that cannot. */
	dns_server?: string | null;
	/** Servers of a site behind a firewall go through this relay agent. Replaces `base_url` and `server_host`. */
	relay_id?: TargetId | null;
	/** Address the servers reach the relay at. */
	relay_host?: string | null;
}

/** Response of `POST /api/agent/ad-kit`: the only chance to see the token and script. */
export interface CreatedAdKit {
	token: AgentToken;
	secret: string;
	/** Content of the PowerShell deployment script (it contains the token). */
	script: string;
	/** File name to save it under, `Deploy-DumbMonit.ps1`. */
	filename: string;
	/** `group_name` of the targets this deployment enrols. */
	folder: string;
	install_windows: string;
	/** URL the agents contact, as written in the kit. */
	server_url: string;
	/** DNS server written in the kit, if any. */
	dns_server: string | null;
}

/**
 * `GET /api/targets/{id}/agent`: the machine as its agent last described it.
 * Mirrors `AgentHostView` in `crates/server/src/api/agent_commands.rs`.
 */
export interface AgentHost {
	hostname: string;
	os: string;
	os_version: string | null;
	arch: string | null;
	agent_version: string;
	/**
	 * True only when the agent said it runs commands. An agent older than the
	 * command channel, or configured with `commands: false`, never picks up a
	 * Restart/Update — the UI must not offer them.
	 */
	commands_supported: boolean;
	/** True when the agent declared `relay: true`: it runs probes for other devices. */
	relay: boolean;
	/** Site declared by the agent, if any. */
	site: string | null;
	/**
	 * Relay mode asked from the UI (or by the enrolment token), sent to the agent
	 * in every acknowledgement. Differs from `relay` until the agent adopts it.
	 * Absent on an older server.
	 */
	relay_wanted?: boolean;
	relay_wanted_site?: string | null;
	/** False: the agent is too old to follow `relay_wanted` (set `relay: true` in agent.yaml, or update it). */
	relay_control?: boolean;
	/** `relay: true` is set in the agent's own configuration, which wins: it can't be switched off here. */
	relay_local?: boolean;
	/** Devices reached through this agent (`via_agent`). */
	relayed: number;
	last_seen_at: string | null;
	/**
	 * Where this machine stands on binding:
	 *
	 * - `bound` — the agent holds a secret of its own, so no other machine can
	 *   push in its name or take its container commands;
	 * - `unbound` — enrolled before binding and never bound: its batches,
	 *   commands and relayed probes are refused until it is re-enrolled.
	 */
	binding: 'bound' | 'unbound';
	/** True for `bound`. */
	bound: boolean;
	bound_at: string | null;
	/** False for an agent binary older than binding: it must be reinstalled. */
	binding_supported: boolean;
	/** End of a re-enrolment window someone opened, while it still runs. */
	rebind_until: string | null;
	/**
	 * Gateway for the agents of its site (a relay only): port asked from the UI
	 * (`null`: closed), port it reports listening on, address the site reaches
	 * it at, agents connected through it right now. Absent on an older server.
	 */
	gateway_wanted?: number | null;
	gateway_port?: number | null;
	gateway_host?: string | null;
	gateway_tunnels?: number;
	/** The relay's last test of its own gateway. Mirrors `GatewayCheck` in `crates/proto/src/push.rs`. */
	gateway_check?: GatewayCheck | null;
	/** The gateway as the relay really opened it (bound address, or why it could not listen). */
	gateway_state?: GatewayState | null;
	/** What keeps the gateway from accepting the site's machines, when known (offline aside). */
	gateway_problem?: GatewayProblem | null;
	/**
	 * Server the agent reports to when its configuration lists several
	 * (`server_urls`): the primary or a backup. `null` with a single address;
	 * absent on an older server.
	 */
	server_link?: ServerLink | null;
	/**
	 * Its last encrypted batch came through the agent WebSocket of the web
	 * address (Cloudflare Tunnel, a reverse proxy) rather than straight to the
	 * agent port. Seen by the server. Absent on an older server.
	 */
	via_websocket?: boolean;
}

/**
 * A relay's test of its own gateway: it connected to `address` as a machine of
 * its site would, and reached this server through it (or not, and why).
 */
export interface GatewayCheck {
	/** `host:port` tested. */
	address: string;
	ok: boolean;
	error?: string | null;
	checked_at_ms: number;
}

/** A relay's gateway as it really opened it. Mirrors `GatewayState` in `crates/proto/src/push.rs`. */
export interface GatewayState {
	/** `host:port` asked: `gateway_listen` of its agent.yaml, else every interface on the port set here. */
	wanted: string;
	/** `host:port` really bound; absent when opening failed. */
	listen?: string | null;
	/** Why the port could not be opened (English, from the relay). */
	error?: string | null;
	/** The address comes from `gateway_listen` on the relay, which wins over this interface. */
	local?: boolean;
	/** The relay talks to the server on the encrypted channel: without it, no tunnel. */
	encrypted?: boolean;
}

/**
 * What keeps a relay's gateway from accepting the machines of its site.
 * Mirrors `GatewayProblem` in `crates/server/src/collectors/agent/gateway.rs`.
 */
export type GatewayProblem = 'closed' | 'too_old' | 'offline' | 'bind_failed' | 'loopback' | 'no_tunnel';

/**
 * Address of the server an agent uses among those of its configuration
 * (`server_url`, then `server_urls`). Mirrors `ServerLink` in
 * `crates/proto/src/push.rs`.
 */
export interface ServerLink {
	/** Rank of the address in use: 0 for the primary. */
	active: number;
	/** Addresses configured, the primary included. */
	servers: number;
	/** Address in use, `https://host:port`. */
	url: string;
	/** When the agent moved to a backup server (Unix ms); absent on the primary. */
	since_ms?: number | null;
	/** Last error seen on the primary, in English; absent on the primary. */
	primary_error?: string | null;
}

/** Response of `POST /api/targets/{id}/agent/rebind`. */
export interface RebindWindow {
	rebind_until: string;
	minutes: number;
}

/**
 * A command queued for an agent (`CommandView` in `api/agent_commands.rs`):
 * container actions, remediation, `agent.uninstall`, or a kind this build does
 * not know. `cancelled`: pulled back before the agent took it; `expired`: no
 * agent came for it within ten minutes.
 */
export interface AgentCommandView {
	id: number;
	target_id: TargetId;
	kind: string;
	args: Record<string, unknown>;
	status: 'queued' | 'running' | 'done' | 'failed' | 'cancelled' | 'expired';
	requested_by: string | null;
	created_at: string;
	started_at: string | null;
	finished_at: string | null;
	result: string | null;
}

/**
 * A service the agent can detect on its machine (`GET /api/targets/{id}/agent/modules`).
 * Each found one is its own `agent_service` device under the machine, with
 * `profile_id` set to the module id.
 */
export interface AgentModule {
	/** `docker`, `plakar`, `backup_repos`, `databases`, `zfs`, `libvirt`, `wireguard`, `ipsec`, `speedtest` — or one this build does not know. */
	id: string;
	/** Display name, for a module the UI has no translation for. */
	label: string;
	/** The agent has reported it on this machine. */
	detected: boolean;
	/** Ticked: a device exists (or will) for it. */
	enabled: boolean;
	/** Nobody ticked or unticked it: the device follows detection. */
	automatic: boolean;
	target_id: number | null;
	last_seen_at: string | null;
}

// --- Windows event log rules of an agent machine (`collectors/agent/eventlog.rs`) ---

/** Event Viewer level. `information` also covers level 0, the level of Security audit events. */
export type AgentEventLevel = 'critical' | 'error' | 'warning' | 'information';

/** What the API accepts to create or replace a rule. */
export interface AgentEventRuleInput {
	name: string;
	/** `System`, `Application`, `Security` or a channel such as `Microsoft-Windows-TaskScheduler/Operational`. */
	channel: string;
	/** Event source (provider); empty or null for any. */
	provider?: string | null;
	/** `4625, 7000-7099`; empty for any. */
	event_ids?: string;
	/** Empty for any level. */
	levels?: AgentEventLevel[];
	/** Text the message must contain (case-insensitive), or a regular expression. */
	pattern?: string | null;
	pattern_regex?: boolean;
	severity?: AlertSeverity;
	enabled?: boolean;
}

export interface AgentEventRule {
	id: number;
	target_id: number;
	name: string;
	channel: string;
	provider: string | null;
	/** Canonical form; empty for any. */
	event_ids: string;
	levels: AgentEventLevel[];
	pattern: string | null;
	pattern_regex: boolean;
	severity: AlertSeverity;
	enabled: boolean;
	matches_total: number;
	/** Events the agent skipped because of the rate limit. */
	dropped_total: number;
	/** Last event received (UTC, no suffix). */
	last_match_at: string | null;
}

/** An example offered when adding a rule; never created on its own. */
export interface AgentEventRulePreset {
	/** Stable key: `failed_logon`, `account_locked`, `unexpected_reboot`, `service_crashed`, `disk_errors`, `log_cleared`, `application_errors`. */
	id: string;
	name: string;
	channel: string;
	provider: string | null;
	event_ids: string;
	levels: AgentEventLevel[];
	severity: AlertSeverity;
}

export interface AgentEventRules {
	/** The machine runs Windows; elsewhere rules are kept but never sent. */
	supported: boolean;
	/** Events kept per rule and per minute. */
	max_per_minute: number;
	rules: AgentEventRule[];
	presets: AgentEventRulePreset[];
}

/** A Windows event matched by one of the machine's rules. */
export interface AgentEvent {
	id: number;
	/** Null once the rule is deleted. */
	rule_id: number | null;
	rule_name: string;
	severity: AlertSeverity;
	channel: string;
	provider: string;
	event_id: number;
	/** Null for "Verbose". */
	level: AgentEventLevel | null;
	record_id: number;
	computer: string;
	message: string;
	occurred_at: string | null;
	received_at: string | null;
}

// --- Agent self-update (Settings → Agents → Agent updates) -------------------

export type AgentUpdateWindow = 'any' | 'maintenance' | 'manual';
export interface AgentUpdateSettings {
	enabled: boolean;
	window: AgentUpdateWindow;
	canary_minutes: number;
	allow_unsigned: boolean;
}
export type AgentUpdateStatus =
	| 'up_to_date'
	| 'pending'
	| 'updating'
	| 'failed'
	| 'refused'
	| 'disabled'
	| 'manual'
	| 'waiting_window'
	| 'waiting_canary'
	/** Rollout waves: its wave is not open yet. */
	| 'waiting_wave'
	/** The rollout is paused. */
	| 'paused'
	/** The rollout stopped: too many agents failed in a wave. */
	| 'halted'
	| 'newer'
	| 'legacy'
	| 'container'
	| 'read_only'
	| 'disabled_locally'
	| 'unsupported'
	| 'no_binary'
	/** The shipped build has no signature and unsigned builds are not accepted. */
	| 'unsigned'
	/** Windows agent before 0.20.2: it cannot replace its own binary, reinstall it once. */
	| 'reinstall'
	/** Agent before 0.20.1: it does not know the current signing key and unsigned builds are not accepted. */
	| 'unknown_key';
/** One rollout wave: how it picks agents among those the previous waves left. */
export type AgentUpdateWave =
	| { by: 'count'; value: number }
	/** Cumulative: enough agents for the waves so far to cover this share of the fleet. */
	| { by: 'percent'; value: number }
	| { by: 'site'; value: string }
	/** The folder of the device. */
	| { by: 'group'; value: string }
	| { by: 'tag'; key: string; value?: string | null };
export interface AgentUpdateWaveView {
	/** `null`: the implicit last wave, every agent the others did not take. */
	select: AgentUpdateWave | null;
	members: number;
	updated: number;
	failed: number;
	state: 'done' | 'active' | 'waiting' | 'upcoming';
}
export interface AgentUpdateRolloutPolicy {
	waves: AgentUpdateWave[];
	delay_minutes: number;
	/** Share of failed agents in a wave that stops the rollout; 0 never stops. */
	max_failure_percent: number;
}
export interface AgentUpdateRollout {
	canaries: number;
	canaries_updated: number;
	open: boolean;
	reason: string | null;
	policy: AgentUpdateRolloutPolicy;
	paused: boolean;
	halted: { wave: number; failed: number; attempted: number } | null;
	/** Empty without waves (canary agents first). */
	waves: AgentUpdateWaveView[];
	/** Rank, from 1, of the wave being updated. */
	current_wave: number | null;
	/** UTC, no suffix; only when the delay alone holds the next wave back. */
	next_wave_at: string | null;
}
export interface AgentUpdateOutcome {
	outcome: 'succeeded' | 'failed' | 'rolled_back' | 'refused';
	version: string | null;
	reason: string | null;
	at: string | null;
}
export interface AgentUpdateAgent {
	id: number;
	name: string;
	hostname: string;
	version: string;
	platform: string | null;
	sha256: string | null;
	/** `null` = follow the global setting. */
	enabled: boolean | null;
	canary: boolean;
	requested: boolean;
	/** Rank, from 1, of its rollout wave; `null` without waves. */
	wave: number | null;
	status: AgentUpdateStatus;
	reason: string | null;
	last: AgentUpdateOutcome | null;
	last_seen_at: string | null;
}
/** `GET /api/agent/updates`. */
export interface AgentUpdates {
	settings: AgentUpdateSettings;
	version: string;
	build: string | null;
	/** Updates are blocked: a shipped build is unsigned and unsigned builds are not accepted. */
	blocked_unsigned: boolean;
	binaries: { platform: string; sha256: string; signed: boolean }[];
	rollout: AgentUpdateRollout;
	agents: AgentUpdateAgent[];
}

// --- Sentinel mode of an agent (`/api/targets/{id}/agent/sentinel`) ------------

/** The notification channel; sent to the server, never read back. */
export type SentinelChannel =
	| { kind: 'webhook'; url: string }
	| { kind: 'ntfy'; server: string; topic: string };

export interface AgentSentinelInput {
	enabled: boolean;
	/** Plain `https://` addresses, 5 at most. */
	urls: string[];
	/** Optional SHA-256 fingerprint (hex) of the certificate expected for an address. */
	pins?: Record<string, string>;
	/** 15 to 3600. */
	interval_secs: number;
	/** Consecutive failures of one address before alerting, 1 to 20. */
	threshold: number;
	/** Omitted: the stored channel is kept. */
	channel?: SentinelChannel;
	/** Removes the stored channel. */
	clear_channel?: boolean;
}

export interface AgentSentinel {
	enabled: boolean;
	urls: string[];
	pins: Record<string, string>;
	interval_secs: number;
	threshold: number;
	/** The agent's last report came over the encrypted channel: required to be a sentinel. */
	encrypted: boolean;
	/** A channel is stored; its content never comes back. */
	has_secret: boolean;
	channel_kind: 'webhook' | 'ntfy' | null;
}

/** A place picked for the wall's weather. Mirrors `weather::Place`. */
export interface WallWeatherPlace {
	name: string;
	region?: string | null;
	country?: string | null;
	latitude: number;
	longitude: number;
}

export type WallWeatherCondition = 'clear' | 'partly_cloudy' | 'cloudy' | 'fog' | 'rain' | 'snow' | 'thunder';

/** `GET /api/wall/weather`: the setting and, when a place is chosen, the weather there now. */
export interface WallWeather {
	place: WallWeatherPlace | null;
	unit: 'c' | 'f';
	/** Null without a place, or when the weather service does not answer: the wall shows nothing. */
	current: {
		/** Outside temperature in `unit`, rounded. */
		temperature: number;
		condition: WallWeatherCondition;
		is_day: boolean;
	} | null;
}

/** Encryption of the connection to the email server. */
export type MailSecurity = 'starttls' | 'tls' | 'none';

/** `GET /api/notify/mail-server` — the password never comes back. */
export interface MailServer {
	host: string;
	/** `null`: the usual port of `security`. */
	port: number | null;
	/** `port`, or 587 / 465 / 25 after `security`. */
	effective_port: number;
	security: MailSecurity;
	/** Empty: no authentication. */
	username: string;
	has_password: boolean;
	from_address: string;
	/** Display name of the sender; empty: the address alone. */
	from_name: string;
	/** A host and a sender are set. */
	configured: boolean;
	/** Set by the `DUMBMONIT_SMTP_*` environment variables: read-only. */
	locked_by_env: boolean;
}

/** `PUT /api/notify/mail-server`. `secrets` omitted keeps the password, `{}` clears it. */
export interface MailServerPayload {
	host: string;
	port: number | null;
	security: MailSecurity;
	username: string;
	from_address: string;
	from_name: string;
	secrets?: { password?: string };
}

export interface MailServerTestReport {
	ok: boolean;
	message: string;
}

// --- Change markers (`/api/annotations`, mirrors `crates/server/src/annotations`) ---

/** Where a marker applies. Mirrors `annotations::Scope`. */
export type AnnotationScope =
	| { kind: 'global' }
	| { kind: 'monitors'; targets: number[] }
	| { kind: 'folder'; folder: string }
	| { kind: 'tags'; tags: string[] };

export type AnnotationSource = 'api' | 'ui' | 'ci';

/** Mirrors `annotations::Annotation`. Times are UTC without suffix (`parseServerDate`). */
export interface Annotation {
	id: number;
	at: string;
	/** End of the window, null for a single instant. */
	until: string | null;
	title: string;
	text: string;
	link: string;
	tags: string[];
	scope: AnnotationScope;
	source: AnnotationSource;
	/** Account, or `token:name`. */
	author: string;
	created_at: string;
}

/** Body of `POST /api/annotations`. `at` defaults to now on the server. */
export interface AnnotationPayload {
	title: string;
	at?: string;
	until?: string | null;
	text?: string;
	link?: string;
	tags?: string[];
	scope?: AnnotationScope;
	source?: AnnotationSource;
}

/** Mirrors `annotations::AfterChange`. */
export interface AfterChange {
	id: number;
	title: string;
	at: string;
}
